// Generates the consumer's Cloudflare Pages Functions as BUILD ARTIFACTS
// (gitignored). Each generated file only wires a package factory with
// build-injected config; the logic lives in the package (functions/commit.js)
// and upgrades via `yarn up`, so the consumer repo never carries Function code.
import './load-env.mjs';
import { writeFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
import { execFileSync } from 'node:child_process';
import { FUNCTIONS_DIR, VAULT_DIR } from './paths.mjs';

// owner/name of the vault repo, injected as the Function's default (runtime
// env GITHUB_REPO still wins). Generic: env override, else the git remote.
function detectRepo() {
  const fromEnv = process.env.WEB_VAULT_REPO || process.env.GITHUB_REPO;
  if (fromEnv) return fromEnv;
  try {
    const url = execFileSync('git', ['remote', 'get-url', 'origin'], {
      cwd: VAULT_DIR,
      encoding: 'utf8',
    }).trim();
    const m = url.match(/[:/]([^/:]+\/[^/]+?)(?:\.git)?$/);
    if (m) return m[1];
  } catch {
    /* no remote */
  }
  return '';
}

// CF_PAGES_BRANCH is the branch the deployment starts from (present only in the
// Cloudflare build); baked so the Function commits to that same branch.
const buildBranch = process.env.CF_PAGES_BRANCH || 'main';
const repo = detectRepo();

const apiDir = join(FUNCTIONS_DIR, 'api');
mkdirSync(apiDir, { recursive: true });

const config = JSON.stringify({ buildBranch, repo });
writeFileSync(
  join(apiDir, 'commit.js'),
  `// GENERATED by web-vault (wv build). Do not edit; this file is gitignored.\n` +
    `import { makeCommitHandler } from 'web-vault/functions/commit.js';\n` +
    `export const onRequestPost = makeCommitHandler(${config});\n`
);
console.log(`[functions] functions/api/commit.js (branch ${buildBranch}, repo ${repo || 'n/a'})`);
